/* ===== 単価の計算 =====
   シートが持っているのは月額（売上・原価・粗利）とコマ数と稼働時刻だけなので、
   1日あたり・1時間あたりはここで割り戻す。
   0 除算や時刻欠損は NaN で返し、表示側で「-」にする。 */

/** "13:00:00.000Z" → 13.0（時間） */
const parseHours = (value) => {
  if (!value) return NaN;
  const [hour, minute] = String(value).split(":").map(Number);
  if (!Number.isFinite(hour) || !Number.isFinite(minute)) return NaN;
  return hour + minute / 60;
};

/** 拘束時間（時間）。終了が開始より前なら日跨ぎとみなす */
const workHours = (row) => {
  const start = parseHours(row["OperationStartTime__c"]);
  const end = parseHours(row["OperationEndTime__c"]);
  if (!Number.isFinite(start) || !Number.isFinite(end)) return NaN;
  const span = end >= start ? end - start : end + 24 - start;
  return span > 0 ? span : NaN;
};

/** 1コマ（＝1日）あたりの単価。月額 ÷ コマ数 */
const perDay = (row, column) => {
  const slots = toNumber(row["KADO_YOTEI_NISSUU_AUTO__c"]);
  if (!slots) return NaN;
  return toNumber(row[column]) / slots;
};

/** 時間当たり売上 = 売上/月 ÷ コマ数 ÷ 拘束時間 */
const salesPerHour = (row) => {
  const daily = perDay(row, "Scheduled_sales_calculation__c");
  const hours = workHours(row);
  if (!Number.isFinite(daily) || !Number.isFinite(hours)) return NaN;
  return daily / hours;
};

/* ===== 時間帯（ヒートマップ） =====
   案件がどの曜日・何時台に稼働しているか。曜日（WorkingDay__c）と
   稼働開始・終了時刻から出す。一覧の「拘束」列と同じ根拠にしておく。
   シートには曜日×時間の稼働フラグ列もあるが、範囲外の列（AI以降）を
   この画面では読まない方針なので使っていない（RANGE_ASSIGN のコメント参照）。 */

/** "月;火" → [0, 1]（HEAT_DAYS の添字）。祝日は行を設けないので落とす */
const workDayIndexes = (row) =>
  (row["WorkingDay__c"] || "")
    .split(";")
    .map((day) => HEAT_DAYS.indexOf(DAY_MAP[day.trim()] || day.trim()))
    .filter((index) => index >= 0);

/**
 * 案件が稼働するマス。"曜日添字-時" → そのマスで稼働している時間（h）の Map で返す。
 * 開始〜終了に1分でも掛かる時間帯を数える（01:00〜05:30 なら 1〜5時台、5時台は0.5h）。
 * 時間は曜日ごとの延べ時間に使う。
 * 0時をまたぐ分は翌日の曜日に入れる（日曜の深夜は月曜へ回る）。
 * 曜日か時刻が欠けていて出せなければ null。
 */
const workSlots = (row) => {
  const start = parseHours(row["OperationStartTime__c"]);
  const span = workHours(row);
  const days = workDayIndexes(row);
  if (!Number.isFinite(start) || !Number.isFinite(span) || !days.length) return null;

  const first = Math.floor(start);
  const last = Math.ceil(start + span) - 1;
  const end = start + span;
  const slots = new Map();
  days.forEach((day) => {
    for (let hour = first; hour <= last; hour++) {
      const key = `${(day + Math.floor(hour / 24)) % 7}-${hour % 24}`;
      const covered = Math.min(end, hour + 1) - Math.max(start, hour);
      slots.set(key, (slots.get(key) || 0) + covered);
    }
  });
  return slots;
};

const slotKey = (day, hour) => `${day}-${hour}`;

const ALL_CATEGORIES = HEAT_CATEGORIES.map((cat) => cat.key);

/**
 * 時間帯区分。正午を境に「午前のみ／午前午後またぎ／午後のみ」。
 * 夜に始まり0時をまたぐ案件は、始まりが午後なので「午後のみ」に入れる。
 * 時刻が欠けていれば null。
 */
const timeCategory = (row) => {
  const start = parseHours(row["OperationStartTime__c"]);
  const span = workHours(row);
  if (!Number.isFinite(start) || !Number.isFinite(span)) return null;
  if (start + span <= 12) return "am";
  if (start >= 12) return "pm";
  return "span";
};

/**
 * [曜日7][時24] の { count, partners, hours }。
 * hours はそのマスの延べ稼働時間（案件ごとの稼働時間の合計）。
 * excluded は時間帯を出せなかった案件数
 */
const buildHeatmap = (rows, slotsOf) => {
  const partnerSets = HEAT_DAYS.map(() =>
    Array.from({ length: 24 }, () => new Set())
  );
  const grid = HEAT_DAYS.map(() =>
    Array.from({ length: 24 }, () => ({ count: 0, partners: 0, hours: 0 }))
  );
  let excluded = 0;

  rows.forEach((row) => {
    const slots = slotsOf(row);
    if (!slots) {
      excluded += 1;
      return;
    }
    // パートナーIDが無い行は名前で代用する（同名の別会社は区別できないが、数えないよりよい）
    const partner = row["Partner__r.ID_18__c"] || row["Partner__r.Name"] || "";
    slots.forEach((hours, key) => {
      const [day, hour] = key.split("-").map(Number);
      grid[day][hour].count += 1;
      grid[day][hour].hours += hours;
      if (partner) partnerSets[day][hour].add(partner);
    });
  });

  grid.forEach((hours, day) =>
    hours.forEach((cell, hour) => {
      cell.partners = partnerSets[day][hour].size;
    })
  );
  return { grid, excluded };
};

/** 粗利率（%）= 粗利/月 ÷ 売上/月 */
const grossMarginPct = (row) => {
  const sales = toNumber(row["Scheduled_sales_calculation__c"]);
  if (!sales) return NaN;
  return (toNumber(row["Yotei_Arari_Keisan__c"]) / sales) * 100;
};

