const loadCachedFilters = () => {
  try {
    const raw = localStorage.getItem(FILTER_CACHE_KEY);
    const parsed = raw ? JSON.parse(raw) : null;
    return parsed && typeof parsed === "object" ? parsed : {};
  } catch (error) {
    console.error("絞り込み条件の復元に失敗しました", error);
    return {};
  }
};

const toArray = (value) => (Array.isArray(value) ? value.filter((v) => typeof v === "string") : []);

/* ===== 絞り込みチップ ===== */

const FacetGroup = ({
  title,
  options,
  selected,
  onToggle,
  onClear,
  onSelectAll,
  renderLabel,
  lockedMessage,
  // 選択肢が数十個ある facet 向け。高さを抑えてスクロールさせる
  scrollable,
  // 同じく数十個ある facet 向けの絞り込み欄。
  // { value, onChange, placeholder, total } を渡すと、
  // 入力欄と「選択中」の行（スクロールで見失わないため）を出す。
  search,
}) => {
  // 「すべて選択」は今表示している選択肢に対して効く。
  // 検索で絞っているときは、その結果だけが対象になる。
  const allSelected =
    options.length > 0 && options.every(({ value }) => selected.includes(value));

  const renderChip = ({ value, count }) => {
    const isOn = selected.includes(value);
    return (
      <button
        key={value}
        type="button"
        className={`ga-chip${isOn ? " is-on" : ""}${count === 0 ? " is-empty" : ""}`}
        onClick={() => onToggle(value)}
        aria-pressed={isOn}
      >
        <span className="ga-chip__label">
          {renderLabel ? renderLabel(value) : value}
        </span>
        <span className="ga-chip__count">{count}</span>
      </button>
    );
  };

  return (
    <div className={`ga-facet${scrollable ? " ga-facet--scroll" : ""}`}>
      <div className="ga-facet__head">
        <span className="ga-facet__title">
          {title}
          {selected.length > 0 && (
            <span className="ga-facet__badge">{selected.length}</span>
          )}
        </span>
        <span className="ga-facet__actions">
          {onSelectAll && (
            <button
              type="button"
              className="clear-btn"
              onClick={onSelectAll}
              disabled={Boolean(lockedMessage) || allSelected}
              title={
                search?.value
                  ? "絞り込んだ結果をすべて選びます"
                  : "表示中の選択肢をすべて選びます"
              }
            >
              すべて選択
            </button>
          )}
          <button
            type="button"
            className="clear-btn"
            onClick={onClear}
            disabled={!selected.length}
          >
            クリア
          </button>
        </span>
      </div>

      {/* 選択中の値。一覧をスクロールしても、何を選んだかは常に見えるようにする */}
      {search && selected.length > 0 && (
        <div className="ga-facet__selected">
          {selected.map((value) => (
            <button
              key={value}
              type="button"
              className="ga-chip is-on"
              onClick={() => onToggle(value)}
              aria-label={`${value} を解除`}
              title="クリックで解除"
            >
              <span className="ga-chip__label">
                {renderLabel ? renderLabel(value) : value}
              </span>
              <span className="ga-chip__remove" aria-hidden="true">
                ×
              </span>
            </button>
          ))}
        </div>
      )}

      {search && (
        <div className="ga-facet__search">
          <input
            type="text"
            value={search.value}
            onChange={(e) => search.onChange(e.target.value)}
            placeholder={search.placeholder}
            aria-label={`${title}を名前で絞り込み`}
          />
          {search.value && (
            <button
              type="button"
              className="ga-facet__search-clear"
              onClick={() => search.onChange("")}
              aria-label="入力を消す"
            >
              ×
            </button>
          )}
          <span className="ga-facet__hint">
            {options.length}/{search.total}
          </span>
        </div>
      )}

      {lockedMessage ? (
        <p className="ga-facet__empty">{lockedMessage}</p>
      ) : options.length === 0 ? (
        <p className="ga-facet__empty">
          {search?.value
            ? `「${search.value}」に一致する候補がありません。`
            : "該当する値がありません。"}
        </p>
      ) : (
        <div className="ga-facet__chips">{options.map(renderChip)}</div>
      )}
    </div>
  );
};

const GeneralAnalysisPage = () => {
  const [allRows, setAllRows] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [authExpired, setAuthExpired] = useState(false);

  // 列数が多いため、狭い画面では表ではなくカードで描く
  const isNarrow = useMediaQuery("(max-width: 768px)");
  const listTopRef = useRef(null);

  const cached = useMemo(loadCachedFilters, []);
  const [selectedGroups, setSelectedGroups] = useState(() => toArray(cached.selectedGroups));
  const [selectedBranches, setSelectedBranches] = useState(() => toArray(cached.selectedBranches));
  const [selectedAdmins, setSelectedAdmins] = useState(() => toArray(cached.selectedAdmins));
  const [selectedContracts, setSelectedContracts] = useState(() =>
    toArray(cached.selectedContracts)
  );
  const [projectKeyword, setProjectKeyword] = useState(() =>
    typeof cached.projectKeyword === "string" ? cached.projectKeyword : ""
  );
  const [partnerKeyword, setPartnerKeyword] = useState(() =>
    typeof cached.partnerKeyword === "string" ? cached.partnerKeyword : ""
  );
  // 管理担当者チップの絞り込み欄。何で絞ったかは条件ではないので保存しない。
  const [adminKeyword, setAdminKeyword] = useState("");

  // 詳細条件（管理担当者・案件名・パートナー名）の開閉。
  // 前回の条件が残っているときは、隠れたまま効いているのを避けて開いた状態で始める。
  const [showDetail, setShowDetail] = useState(
    () =>
      toArray(cached.selectedAdmins).length > 0 ||
      Boolean(cached.projectKeyword) ||
      Boolean(cached.partnerKeyword)
  );

  // 並び順は保存しない。開くたびに「指定なし」（＝シートの並び）から始める。
  const [sortConfig, setSortConfig] = useState({ key: null, direction: "asc" });
  const [currentPage, setCurrentPage] = useState(1);

  // 内訳の切り口と指標。件数が多い切り口は既定で上位のみ出す
  // 保存済みの値でも、選択肢から消えていれば既定に戻す
  const [breakdownKey, setBreakdownKey] = useState(() =>
    BREAKDOWN_DIMENSIONS.some((d) => d.key === cached.breakdownKey)
      ? cached.breakdownKey
      : BREAKDOWN_DIMENSIONS[0].key
  );
  const [breakdownMetric, setBreakdownMetric] = useState(() =>
    BREAKDOWN_METRICS.some((m) => m.key === cached.breakdownMetric)
      ? cached.breakdownMetric
      : BREAKDOWN_METRICS[0].key
  );
  const [showAllBreakdown, setShowAllBreakdown] = useState(false);

  // 内訳の行をクリックしたときの掘り下げ。{ dimension, value }
  // 内訳の集計自体はこれを無視し、下の明細と件数だけを絞る。
  const [drill, setDrill] = useState(null);

  // 一覧の代わりに曜日×時間帯のヒートマップを出すか。開くたびに一覧から始める
  const [listView, setListView] = useState("list");
  const [heatMetric, setHeatMetric] = useState("count");
  // ヒートマップに含める時間帯区分と、区分ごとに表を分けるか
  const [heatCats, setHeatCats] = useState(ALL_CATEGORIES);
  const [heatSplit, setHeatSplit] = useState(false);
  // ヒートマップのマスを押したときの絞り込み。{ day, hour, cats }
  // cats は押したときの時間帯区分。一覧にも同じ区分で絞り込みをかける
  const [slot, setSlot] = useState(null);

  useDebouncedSave(FILTER_CACHE_KEY, {
    selectedGroups,
    selectedBranches,
    selectedAdmins,
    selectedContracts,
    projectKeyword,
    partnerKeyword,
    breakdownKey,
    breakdownMetric,
  });

  /* ===== データ取得（sheetsApi 側でキャッシュされるため再訪時は即時） =====
     silent: 全画面スピナーを出さずに取り直す。
     引いて更新はそれ自身がインジケータを出すため、二重に回さない。 */
  const loadData = useCallback(async ({ force = false, silent = false } = {}) => {
    if (!silent) setLoading(true);
    setError("");
    setAuthExpired(false);
    try {
      setAllRows(await fetchSheetRows(RANGE_ASSIGN, { force }));
    } catch (e) {
      console.error(e);
      if (isAuthError(e)) setAuthExpired(true);
      else setError("データ取得中にエラーが発生しました。");
    } finally {
      if (!silent) setLoading(false);
    }
  }, []);

  useEffect(() => {
    loadData();
  }, [loadData]);

  /* ===== 絞り込み ===== */
  const normalizedProject = useMemo(
    () => normalizeText(projectKeyword),
    [projectKeyword]
  );
  const normalizedPartner = useMemo(
    () => normalizeText(partnerKeyword),
    [partnerKeyword]
  );

  // facet ごとの判定を分けて持つ。
  // 選択肢の件数を出すとき「その facet だけ外した集合」が要るため。
  // 案件名とパートナー名は別の欄なので、両方入っていれば AND になる。
  const predicates = useMemo(
    () => ({
      group: (row) =>
        !selectedGroups.length || selectedGroups.includes(cellValue(row, "Group_FY22__c")),
      branch: (row) =>
        !selectedBranches.length || selectedBranches.includes(cellValue(row, "Branch__c")),
      admin: (row) =>
        !selectedAdmins.length || selectedAdmins.includes(cellValue(row, ADMIN_KEY)),
      contract: (row) =>
        !selectedContracts.length ||
        selectedContracts.includes(cellValue(row, CONTRACT_KEY)),
      project: (row) =>
        !normalizedProject || normalizeText(row["Name"]).includes(normalizedProject),
      partner: (row) =>
        !normalizedPartner ||
        normalizeText(row["Partner__r.Name"]).includes(normalizedPartner),
    }),
    [
      selectedGroups,
      selectedBranches,
      selectedAdmins,
      selectedContracts,
      normalizedProject,
      normalizedPartner,
    ]
  );

  /** except に渡した facet の条件だけ外して絞り込む */
  const rowsExcept = useCallback(
    (except) =>
      allRows.filter((row) =>
        Object.entries(predicates).every(([name, test]) => name === except || test(row))
      ),
    [allRows, predicates]
  );

  // 案件名・パートナー名は、どちらか一方が規定文字数に達していればよい
  const longestKeyword = Math.max(normalizedProject.length, normalizedPartner.length);

  /** 一覧を出してよい状態か（主管＋支店、管理担当者、またはキーワード）。
      管理担当者は1人選べば十分絞れるので、単独で条件として認める。
      （認めないと、担当者を選んでも一覧が出ない不可解な状態になる） */
  const isSearchReady =
    longestKeyword >= KEYWORD_MIN_LENGTH ||
    selectedAdmins.length > 0 ||
    (selectedGroups.length > 0 && selectedBranches.length > 0);

  /** 条件が足りないとき、何が足りないかを1行で返す */
  const missingCondition = () => {
    if (longestKeyword > 0) {
      return `案件名かパートナー名が、あと${
        KEYWORD_MIN_LENGTH - longestKeyword
      }文字必要です。`;
    }
    if (!selectedGroups.length) return "主管が選ばれていません。";
    return "支店が選ばれていません。";
  };

  // 条件を満たすまで絞り込み自体を走らせない（全件を並べ替える無駄を避ける）
  const filteredRows = useMemo(
    () => (isSearchReady ? rowsExcept(null) : []),
    [isSearchReady, rowsExcept]
  );

  /**
   * 選択肢と件数。
   * 選択済みの値は件数0でも必ず残す（消えると解除できなくなるため）。
   */
  const buildOptions = useCallback((rows, column, selected, compare) => {
    const counts = new Map();
    rows.forEach((row) => {
      const value = cellValue(row, column);
      counts.set(value, (counts.get(value) || 0) + 1);
    });
    selected.forEach((value) => {
      if (!counts.has(value)) counts.set(value, 0);
    });
    return Array.from(counts, ([value, count]) => ({ value, count })).sort(compare);
  }, []);

  const byName = (a, b) => a.value.localeCompare(b.value, "ja");

  const groupOptions = useMemo(
    () =>
      buildOptions(
        rowsExcept("group"),
        "Group_FY22__c",
        selectedGroups,
        (a, b) => groupRank(a.value) - groupRank(b.value) || byName(a, b)
      ),
    [buildOptions, rowsExcept, selectedGroups]
  );

  const branchOptions = useMemo(
    () => buildOptions(rowsExcept("branch"), "Branch__c", selectedBranches, byName),
    [buildOptions, rowsExcept, selectedBranches]
  );

  // 持込・業者・雇用・支援の4つ程度なので、件数の多い順に並べる
  const contractOptions = useMemo(
    () =>
      buildOptions(
        rowsExcept("contract"),
        CONTRACT_KEY,
        selectedContracts,
        (a, b) => b.count - a.count || byName(a, b)
      ),
    [buildOptions, rowsExcept, selectedContracts]
  );

  // 人数が多いので、件数順ではなく名前順にして自分の名前を探しやすくする
  const adminOptions = useMemo(
    () => buildOptions(rowsExcept("admin"), ADMIN_KEY, selectedAdmins, byName),
    [buildOptions, rowsExcept, selectedAdmins]
  );

  // 数十人が一度に並ぶと選べないので、入力した文字を含む人だけに絞る。
  // 選択中の人が消えても「選択中」の行に残るため、解除できなくなることはない。
  const visibleAdminOptions = useMemo(() => {
    const keyword = squashText(adminKeyword);
    if (!keyword) return adminOptions;
    return adminOptions.filter(({ value }) => squashText(value).includes(keyword));
  }, [adminOptions, adminKeyword]);

  // 主管を変えたとき、その主管に存在しない支店の選択は落とす。
  // （残すと件数0のまま「該当なし」になり、原因が分かりにくい）
  useEffect(() => {
    if (!selectedGroups.length || !allRows.length) return;
    const available = new Set(
      allRows
        .filter((row) => selectedGroups.includes(cellValue(row, "Group_FY22__c")))
        .map((row) => cellValue(row, "Branch__c"))
    );
    setSelectedBranches((prev) => {
      const next = prev.filter((branch) => available.has(branch));
      return next.length === prev.length ? prev : next;
    });
  }, [selectedGroups, allRows]);

  const toggleValue = (setter) => (value) =>
    setter((prev) =>
      prev.includes(value) ? prev.filter((v) => v !== value) : [...prev, value]
    );

  /** 表示中の選択肢をまとめて選ぶ。検索や他の条件で今は見えていない選択は残す */
  const selectAll = (setter, options) => () =>
    setter((prev) => Array.from(new Set([...prev, ...options.map((o) => o.value)])));

  const hasAnyFilter =
    selectedGroups.length > 0 ||
    selectedBranches.length > 0 ||
    selectedAdmins.length > 0 ||
    selectedContracts.length > 0 ||
    projectKeyword.length > 0 ||
    partnerKeyword.length > 0;

  // 畳んだときに「何が効いているか」を見せるための一行。
  // 隠れたまま条件が効いている状態が一番分かりにくいので、閉じていても必ず出す。
  const detailConditions = [
    selectedAdmins.length ? `管理担当者 ${selectedAdmins.length}人` : "",
    projectKeyword ? `案件名「${projectKeyword}」` : "",
    partnerKeyword ? `パートナー名「${partnerKeyword}」` : "",
  ].filter(Boolean);

  const clearAllFilters = () => {
    setSelectedGroups([]);
    setSelectedBranches([]);
    setSelectedAdmins([]);
    setSelectedContracts([]);
    setProjectKeyword("");
    setPartnerKeyword("");
  };

  // 切り口や絞り込みが変わったら、内訳からの掘り下げは解除する。
  // 残すと「内訳には出ているのに明細が空」という状態になりうるため。
  useEffect(() => {
    setDrill(null);
  }, [
    breakdownKey,
    selectedGroups,
    selectedBranches,
    selectedAdmins,
    selectedContracts,
    normalizedProject,
    normalizedPartner,
  ]);

  // 更新でデータが入れ替わり、掘り下げ中の値が消えていたら解除する。
  // 残すと明細が0件になり、解除ボタンごと画面から消えて戻れなくなる。
  useEffect(() => {
    if (!drill) return;
    const stillExists = filteredRows.some(
      (row) => cellValue(row, drill.dimension) === drill.value
    );
    if (!stillExists) setDrill(null);
  }, [filteredRows, drill]);

  /**
   * 明細と件数に使う行。内訳から掘り下げていればさらに絞る。
   * 内訳の集計そのものは filteredRows のままにして、
   * 掘り下げても他の行が消えないようにしている。
   */
  const drilledRows = useMemo(() => {
    if (!drill) return filteredRows;
    return filteredRows.filter(
      (row) => cellValue(row, drill.dimension) === drill.value
    );
  }, [filteredRows, drill]);

  // 行ごとの稼働マス。ヒートマップと時間帯の絞り込みで何度も引くので先に出しておく
  const slotsByRow = useMemo(
    () => new Map(filteredRows.map((row) => [row, workSlots(row)])),
    [filteredRows]
  );
  const slotsOf = useCallback((row) => slotsByRow.get(row) ?? null, [slotsByRow]);

  /**
   * ヒートマップは内訳からの絞り込みまでを反映し、時間帯の絞り込みは無視する。
   * （効かせると選んだマス以外が薄くなり、全体の中での位置が見えなくなる）
   */
  const heatmap = useMemo(() => buildHeatmap(drilledRows, slotsOf), [drilledRows, slotsOf]);

  const categoryByRow = useMemo(
    () => new Map(filteredRows.map((row) => [row, timeCategory(row)])),
    [filteredRows]
  );

  const categoryCounts = useMemo(() => {
    const counts = {};
    drilledRows.forEach((row) => {
      const cat = categoryByRow.get(row);
      if (cat) counts[cat] = (counts[cat] || 0) + 1;
    });
    return counts;
  }, [drilledRows, categoryByRow]);

  /** 画面に出す表。まとめて表示なら選んだ区分を合算した1枚、区分ごとなら区分の数だけ */
  const heatBlocks = useMemo(() => {
    const rowsIn = (cats) => drilledRows.filter((row) => cats.includes(categoryByRow.get(row)));
    if (!heatSplit) {
      const rows = rowsIn(heatCats);
      return [
        {
          key: "all",
          palette: "teal",
          cats: heatCats,
          total: rows.length,
          grid: buildHeatmap(rows, slotsOf).grid,
        },
      ];
    }
    return HEAT_CATEGORIES.filter((cat) => heatCats.includes(cat.key)).map((cat) => {
      const rows = rowsIn([cat.key]);
      return {
        key: cat.key,
        title: cat.label,
        desc: cat.desc,
        palette: cat.palette,
        cats: [cat.key],
        total: rows.length,
        grid: buildHeatmap(rows, slotsOf).grid,
      };
    });
  }, [drilledRows, categoryByRow, heatCats, heatSplit, slotsOf]);

  /** 区分を含める／外す。最後の1つは外さない（何も出なくなるため） */
  const toggleHeatCat = (key) =>
    setHeatCats((prev) => {
      if (!prev.includes(key)) return ALL_CATEGORIES.filter((k) => k === key || prev.includes(k));
      return prev.length > 1 ? prev.filter((k) => k !== key) : prev;
    });

  /** 明細と件数に使う行。ヒートマップのマスを選んでいれば、その時間帯に稼働する案件だけ */
  const listRows = useMemo(() => {
    if (!slot) return drilledRows;
    const key = slotKey(slot.day, slot.hour);
    return drilledRows.filter(
      (row) => slotsOf(row)?.has(key) && slot.cats.includes(categoryByRow.get(row))
    );
  }, [drilledRows, slot, slotsOf, categoryByRow]);

  // 絞り込みや内訳が変わったら、時間帯の選択は解除する（内訳からの絞り込みと同じ理由）
  useEffect(() => {
    setSlot(null);
  }, [
    drill,
    selectedGroups,
    selectedBranches,
    selectedAdmins,
    selectedContracts,
    normalizedProject,
    normalizedPartner,
  ]);

  // 更新でそのマスの案件が無くなったら解除する。残すと0件の画面から戻れなくなる
  useEffect(() => {
    if (slot && !listRows.length) setSlot(null);
  }, [slot, listRows]);

  /** マスを押したら、その時間帯の案件一覧へ。同じマスをもう一度押したら解除 */
  const selectSlot = (day, hour, cats) => {
    const isSame =
      slot &&
      slot.day === day &&
      slot.hour === hour &&
      slot.cats.length === cats.length &&
      slot.cats.every((key) => cats.includes(key));
    setSlot(isSame ? null : { day, hour, cats });
    if (!isSame) {
      setListView("list");
      listTopRef.current?.scrollIntoView({ behavior: "smooth", block: "start" });
    }
  };

  // 区分を絞っているときだけ、どの区分かを添える
  const slotText = slot
    ? `${HEAT_DAYS[slot.day]}曜 ${slot.hour}時台` +
      (slot.cats.length < ALL_CATEGORIES.length
        ? `（${HEAT_CATEGORIES.filter((cat) => slot.cats.includes(cat.key))
            .map((cat) => cat.label)
            .join("・")}）`
        : "")
    : "";

  /* ===== 集計 ===== */
  const summary = useMemo(() => {
    const total = listRows.reduce(
      (acc, row) => {
        acc.slots += toNumber(row["KADO_YOTEI_NISSUU_AUTO__c"]);
        acc.sales += toNumber(row["Scheduled_sales_calculation__c"]);
        acc.cost += toNumber(row["Yotei_Genka_keisan__c"]);
        acc.profit += toNumber(row["Yotei_Arari_Keisan__c"]);
        return acc;
      },
      { slots: 0, sales: 0, cost: 0, profit: 0 }
    );
    return {
      ...total,
      partners: new Set(
        listRows.map((row) => row["Partner__r.ID_18__c"]).filter(Boolean)
      ).size,
      margin: total.sales ? (total.profit / total.sales) * 100 : NaN,
    };
  }, [listRows]);

  /* ===== 内訳（集計） =====
     絞り込んだ結果に対して集計する。主管＋支店で絞ってから市区町村で切る、
     といった掘り下げ方を想定している。 */
  const breakdown = useMemo(
    () => aggregateBreakdown(filteredRows, breakdownKey, breakdownMetric),
    [filteredRows, breakdownKey, breakdownMetric]
  );

  const breakdownMax = breakdown.length ? breakdown[0][breakdownMetric] : 0;
  const breakdownRows = showAllBreakdown ? breakdown : breakdown.slice(0, BREAKDOWN_LIMIT);
  const hiddenBreakdownCount = breakdown.length - breakdownRows.length;

  const breakdownDimension = BREAKDOWN_DIMENSIONS.find((d) => d.key === breakdownKey);

  /** 同じ行をもう一度押したら解除する */
  const toggleDrill = (value) =>
    setDrill((prev) =>
      prev && prev.dimension === breakdownKey && prev.value === value
        ? null
        : { dimension: breakdownKey, value }
    );

  /* ===== 並び替え ===== */
  const sortedRows = useMemo(() => {
    const header = HEADERS.find((h) => h.key === sortConfig.key);
    if (!header) return listRows;

    const direction = sortConfig.direction === "desc" ? -1 : 1;
    return [...listRows].sort((a, b) => {
      const av = sortValue(a, header);
      const bv = sortValue(b, header);
      if (typeof av === "string" || typeof bv === "string") {
        return String(av).localeCompare(String(bv), "ja") * direction;
      }
      return (av - bv) * direction;
    });
  }, [listRows, sortConfig]);

  const handleSort = (key) =>
    setSortConfig((prev) => ({
      key,
      direction: prev.key === key && prev.direction === "asc" ? "desc" : "asc",
    }));

  /* ===== ページング ===== */
  const totalPages = useMemo(
    () => Math.max(1, Math.ceil(sortedRows.length / PAGE_SIZE)),
    [sortedRows.length]
  );

  const pageRows = useMemo(() => {
    const start = (currentPage - 1) * PAGE_SIZE;
    return sortedRows.slice(start, start + PAGE_SIZE);
  }, [sortedRows, currentPage]);

  // 条件が変われば先頭ページへ戻す
  useEffect(() => {
    setCurrentPage(1);
  }, [
    selectedGroups,
    selectedBranches,
    selectedAdmins,
    selectedContracts,
    normalizedProject,
    normalizedPartner,
    drill,
    slot,
  ]);

  useEffect(() => {
    setCurrentPage((page) => Math.min(page, totalPages));
  }, [totalPages]);

  const handlePageChange = (page) => {
    setCurrentPage(page);
    listTopRef.current?.scrollIntoView({ behavior: "smooth", block: "start" });
  };

  const startIndex = sortedRows.length ? (currentPage - 1) * PAGE_SIZE + 1 : 0;
  const endIndex = Math.min(currentPage * PAGE_SIZE, sortedRows.length);

  /* ===== Excel 出力 =====
     表示中の1ページではなく、今の条件に当てはまる全件を画面と同じ並びで出す。
     ファイルだけ渡されても条件が分かるよう、出力条件を別シートに書く。 */
  const [exporting, setExporting] = useState(false);

  /** ログイン時に控えた Google アカウント。「山田 太郎（taro@example.com）」 */
  const exportedBy = () => {
    try {
      const name = localStorage.getItem("userName");
      const email = localStorage.getItem("userEmail");
      return [name, email && `（${email}）`].filter(Boolean).join("");
    } catch (e) {
      return "";
    }
  };

  const metricLabel =
    BREAKDOWN_METRICS.find((m) => m.key === breakdownMetric)?.label || "件数";

  const describeConditions = (now) => {
    const joinOr = (values, format = (v) => v) =>
      values.length ? values.map((v) => format(v) || v).join("、") : "指定なし";
    const sortHeader = HEADERS.find((h) => h.key === sortConfig.key);
    const drillDimension = drill
      ? BREAKDOWN_DIMENSIONS.find((d) => d.key === drill.dimension)
      : null;

    return [
      ["出力日時", formatDateTime(now)],
      ["出力者", exportedBy() || "不明"],
      // 画面に出ているデータが、シートのいつの更新分か。分からなければそう書く
      ["データ更新日時", formatDateTime(cachedRowsUpdatedAt(RANGE_ASSIGN))],
      ["主管", joinOr(selectedGroups, groupLabel)],
      ["支店", joinOr(selectedBranches)],
      ["契約区分", joinOr(selectedContracts)],
      ["管理担当者", joinOr(selectedAdmins)],
      ["案件名", projectKeyword || "指定なし"],
      ["パートナー名", partnerKeyword || "指定なし"],
      [
        "内訳からの絞り込み",
        drillDimension
          ? `${drillDimension.label}：${
              (drillDimension.format && drillDimension.format(drill.value)) || drill.value
            }`
          : "なし",
      ],
      ["時間帯での絞り込み", slot ? slotText : "なし"],
      [
        "並び順",
        sortHeader
          ? `${sortHeader.label}（${sortConfig.direction === "asc" ? "昇順" : "降順"}）`
          : "指定なし（シートの並び）",
      ],
      ["件数", sortedRows.length],
      [
        "内訳シート",
        `${filteredRows.length.toLocaleString()}件を集計（内訳からの絞り込みは含めない）。` +
          `${metricLabel}の大きい順で、構成比も${metricLabel}の比率`,
      ],
      [
        "時間帯シート",
        `${drilledRows.length.toLocaleString()}件をもとに、各時間帯に稼働している案件数・パートナー数` +
          "（時間帯・時間帯区分での絞り込みは含めない）。0時をまたぐ分は翌日の曜日に数え、祝日は含まない。" +
          (heatmap.excluded
            ? `曜日・稼働時刻が登録されていないか祝日のみの${heatmap.excluded.toLocaleString()}件は数えていない`
            : ""),
      ],
    ];
  };

  const handleExport = async () => {
    if (exporting || !sortedRows.length) return;
    setExporting(true);
    try {
      const now = new Date();
      await downloadWorkbook({
        fileName: timestampedFileName("案件分析", now),
        creator: exportedBy(),
        sheets: [
          {
            name: "案件一覧",
            columns: EXPORT_COLUMNS,
            rows: sortedRows.map((row) => EXPORT_COLUMNS.map((c) => c.value(row))),
          },
          // 内訳は切り口ごとに1シート。画面と同じく内訳からの絞り込みは効かせず、
          // 上位20件で切らずに全件を出す
          ...BREAKDOWN_DIMENSIONS.map((dimension) =>
            breakdownSheet(dimension, filteredRows, breakdownMetric)
          ),
          // 画面のヒートマップと同じく、時間帯の絞り込みは効かせない
          heatmapSheet(heatmap.grid, "count", "案件数"),
          heatmapSheet(heatmap.grid, "partners", "パートナー数"),
          {
            name: "出力条件",
            table: false,
            columns: [
              { header: "項目", width: 18 },
              { header: "内容", width: 60, wrap: true },
            ],
            rows: describeConditions(now),
          },
        ],
      });
    } catch (e) {
      console.error("Excel出力に失敗しました", e);
      window.alert("Excelの作成に失敗しました。時間をおいて再度お試しください。");
    } finally {
      setExporting(false);
    }
  };

  /* ===== セルの描画 ===== */
  const renderCell = (header, row) => {
    switch (header.key) {
      case "Group_FY22__c":
        return groupLabel(row["Group_FY22__c"]);
      case "Name":
        return row["Id"] ? (
          <ConfirmLink
            href={sfLink(row["Id"])}
            description={`案件：${row["Name"] || "案件名不明"}`}
            className="name-link"
          >
            {row["Name"] || "案件名不明"}
          </ConfirmLink>
        ) : (
          row["Name"] || ""
        );
      case "Partner__r.Name":
        return row["Partner__r.ID_18__c"] ? (
          <ConfirmLink
            href={sfLink(row["Partner__r.ID_18__c"])}
            description={`パートナー：${row["Partner__r.Name"] || "不明"}`}
            className="name-link"
          >
            {row["Partner__r.Name"] || "不明"}
          </ConfirmLink>
        ) : (
          row["Partner__r.Name"] || ""
        );
      case "PrefecturesFree__c":
        return formatArea(row);
      case "OperationEndDate__c":
        return formatEndDate(row["OperationEndDate__c"]);
      case "WorkingDay__c":
        return formatWorkingDays(row["WorkingDay__c"]);
      case "KADO_YOTEI_NISSUU_AUTO__c":
        return row["KADO_YOTEI_NISSUU_AUTO__c"] || "";
      case "__hours__":
        return (
          <>
            {formatHours(workHours(row))}
            {formatTimeRange(row) && (
              <span className="ga-sub">{formatTimeRange(row)}</span>
            )}
          </>
        );
      case "__margin__":
        return formatRate(grossMarginPct(row)) || "-";
      case "__salesPerHour__":
        return formatComputed(salesPerHour(row));
      default:
        if (header.type !== "number") return row[header.key] || "";
        // 月額と、その下に1日あたり単価
        return (
          <>
            {formatMoney(row[header.key]) || "-"}
            {header.perDay && (
              <span className="ga-sub">
                （{formatComputed(perDay(row, header.key), "/日")}）
              </span>
            )}
          </>
        );
    }
  };

  /* ===== 表示 ===== */
  return (
    <div className="anken-page">
      <HeaderMenu title="案件分析ページ" />

      <div className="main-content">
        {loading ? (
          <div className="spinner-wrapper">
            <div className="spinner" aria-label="読み込み中" />
            <div className="loading-text">データ取得中です...</div>
          </div>
        ) : authExpired ? (
          <SessionExpiredNotice onRetry={() => loadData({ force: true })} />
        ) : error ? (
          <p style={{ color: "#b00020" }}>{error}</p>
        ) : (
          <>
            {/* 絞り込み */}
            <div className="ga-filters">
              <div className="ga-filters__head">
                <h2 className="ga-filters__title">絞り込み</h2>
                <button
                  type="button"
                  className="clear-btn"
                  onClick={clearAllFilters}
                  disabled={!hasAnyFilter}
                >
                  すべて解除
                </button>
              </div>

              <FacetGroup
                title="主管"
                options={groupOptions}
                selected={selectedGroups}
                onToggle={toggleValue(setSelectedGroups)}
                onClear={() => setSelectedGroups([])}
                onSelectAll={selectAll(setSelectedGroups, groupOptions)}
                renderLabel={groupLabel}
              />
              <FacetGroup
                title="支店"
                options={branchOptions}
                selected={selectedBranches}
                onToggle={toggleValue(setSelectedBranches)}
                onClear={() => setSelectedBranches([])}
                onSelectAll={selectAll(setSelectedBranches, branchOptions)}
                // 主管を選ぶ前は全支店が並んで選びにくいため、順序を固定する
                lockedMessage={
                  selectedGroups.length ? "" : "先に主管を選んでください。"
                }
              />
              <FacetGroup
                title="契約区分"
                options={contractOptions}
                selected={selectedContracts}
                onToggle={toggleValue(setSelectedContracts)}
                onClear={() => setSelectedContracts([])}
                onSelectAll={selectAll(setSelectedContracts, contractOptions)}
              />

              {/* 主管・支店だけで足りることが多いので、残りは畳んでおく。
                  条件が入っているときは、閉じていても見出しの下に出す。 */}
              <div className={`ga-more${showDetail ? " is-open" : ""}`}>
                <button
                  type="button"
                  className="ga-more__toggle"
                  onClick={() => setShowDetail((open) => !open)}
                  aria-expanded={showDetail}
                >
                  <span className="ga-more__arrow" aria-hidden="true">
                    {showDetail ? "▼" : "▶"}
                  </span>
                  <span className="ga-more__title">詳細条件</span>
                  {detailConditions.length > 0 && (
                    <span className="ga-facet__badge">{detailConditions.length}</span>
                  )}
                  <span className="ga-more__summary">
                    {detailConditions.length
                      ? detailConditions.join(" / ")
                      : "管理担当者・案件名・パートナー名"}
                  </span>
                </button>

                {showDetail && (
                  <div className="ga-more__body">
                    <FacetGroup
                      title="管理担当者"
                      options={visibleAdminOptions}
                      selected={selectedAdmins}
                      onToggle={toggleValue(setSelectedAdmins)}
                      onClear={() => setSelectedAdmins([])}
                      onSelectAll={selectAll(setSelectedAdmins, visibleAdminOptions)}
                      scrollable
                      search={{
                        value: adminKeyword,
                        onChange: setAdminKeyword,
                        placeholder: "名前の一部で絞り込み（例: 山田）",
                        total: adminOptions.length,
                      }}
                    />

                    <div className="detail-search">
                      <label className="detail-search__label">
                        案件名で絞り込み
                        <input
                          type="text"
                          value={projectKeyword}
                          onChange={(e) => setProjectKeyword(e.target.value)}
                          placeholder="例: 光合金"
                        />
                      </label>
                      <button
                        type="button"
                        className="detail-search__clear"
                        onClick={() => setProjectKeyword("")}
                        disabled={!projectKeyword}
                      >
                        クリア
                      </button>

                      <label className="detail-search__label">
                        パートナー名で絞り込み
                        <input
                          type="text"
                          value={partnerKeyword}
                          onChange={(e) => setPartnerKeyword(e.target.value)}
                          placeholder="例: 小柳"
                        />
                      </label>
                      <button
                        type="button"
                        className="detail-search__clear"
                        onClick={() => setPartnerKeyword("")}
                        disabled={!partnerKeyword}
                      >
                        クリア
                      </button>
                    </div>

                    <p className="ga-filters__note">
                      案件名かパートナー名が{KEYWORD_MIN_LENGTH}
                      文字以上になるか、管理担当者を選ぶと、主管・支店を選ばなくても一覧が出ます。
                      案件名とパートナー名を両方入れた場合は、その両方に当てはまる案件だけを表示します。
                    </p>
                  </div>
                )}
              </div>
            </div>

            {/* 一覧 */}
            <div ref={listTopRef} />

            {!isSearchReady ? (
              <div className="ga-gate">
                <p className="ga-gate__title">
                  案件を表示するには、次のいずれかを指定してください
                </p>
                <ul className="ga-gate__list">
                  <li>
                    <strong>主管</strong>と<strong>支店</strong>を両方選ぶ
                  </li>
                  <li>
                    または<strong>管理担当者</strong>を選ぶ
                  </li>
                  <li>
                    または<strong>案件名</strong>か<strong>パートナー名</strong>
                    のどちらかを{KEYWORD_MIN_LENGTH}文字以上入力する
                  </li>
                </ul>
                <p className="ga-gate__note">{missingCondition()}</p>
              </div>
            ) : sortedRows.length === 0 ? (
              <p className="ga-empty">
                条件に合う案件がありません。絞り込みを緩めてください。
              </p>
            ) : (
              <>
                {/* 件数と金額のサマリ */}
                <div className="ga-summary">
                  <div className="ga-summary__main">
                    <span className="ga-summary__count">
                      {sortedRows.length.toLocaleString()}
                    </span>
                    <span className="ga-summary__unit">件</span>
                    <span className="ga-summary__total">
                      / 全 {allRows.length.toLocaleString()} 件
                    </span>
                  </div>
                  <dl className="ga-summary__stats">
                    <div>
                      <dt>パートナー数</dt>
                      <dd>{summary.partners.toLocaleString()}</dd>
                    </div>
                    <div>
                      <dt>コマ合計</dt>
                      <dd>{summary.slots.toLocaleString()}</dd>
                    </div>
                    <div>
                      <dt>売上/月</dt>
                      <dd>{summary.sales.toLocaleString()}</dd>
                    </div>
                    <div>
                      <dt>粗利/月</dt>
                      <dd className={summary.profit < 0 ? "is-negative" : ""}>
                        {summary.profit.toLocaleString()}
                      </dd>
                    </div>
                    <div>
                      <dt>粗利率</dt>
                      <dd>{formatRate(summary.margin) || "-"}</dd>
                    </div>
                  </dl>
                </div>

                {/* 内訳 */}
                <div className="ga-breakdown">
                  <div className="ga-breakdown__head">
                    <h2 className="ga-breakdown__title">内訳</h2>
                    <label className="ga-breakdown__metric">
                      並び順
                      <select
                        value={breakdownMetric}
                        onChange={(e) => setBreakdownMetric(e.target.value)}
                      >
                        {BREAKDOWN_METRICS.map((m) => (
                          <option key={m.key} value={m.key}>
                            {m.label}順
                          </option>
                        ))}
                      </select>
                    </label>
                  </div>

                  <div className="ga-breakdown__tabs">
                    {BREAKDOWN_DIMENSIONS.map((d) => (
                      <button
                        key={d.key}
                        type="button"
                        className={`ga-breakdown__tab${
                          d.key === breakdownKey ? " is-on" : ""
                        }`}
                        onClick={() => {
                          setBreakdownKey(d.key);
                          setShowAllBreakdown(false);
                        }}
                        aria-pressed={d.key === breakdownKey}
                      >
                        {d.label}
                      </button>
                    ))}
                  </div>

                  <div className="anken-table-scroll">
                    <table className="anken-table ga-breakdown__table">
                      <thead>
                        <tr>
                          <th className="cell col-m">
                            {
                              BREAKDOWN_DIMENSIONS.find((d) => d.key === breakdownKey)
                                ?.label
                            }
                          </th>
                          <th className="cell col-xs right">件数</th>
                          <th className="cell col-xs right">コマ</th>
                          <th className="cell col-s right">売上/月</th>
                          <th className="cell col-s right">粗利/月</th>
                          <th className="cell col-xs right">粗利率</th>
                          <th className="cell col-xs right">構成比</th>
                        </tr>
                      </thead>
                      <tbody>
                        {breakdownRows.map((entry) => {
                          const label = breakdownDimension?.format
                            ? breakdownDimension.format(entry.value) || entry.value
                            : entry.value;
                          const barWidth = breakdownMax
                            ? (entry[breakdownMetric] / breakdownMax) * 100
                            : 0;
                          const isDrilled = drill?.value === entry.value;
                          return (
                            <tr
                              key={entry.value}
                              className={`ga-breakdown__row${
                                isDrilled ? " is-on" : drill ? " is-dim" : ""
                              }`}
                              role="button"
                              tabIndex={0}
                              aria-pressed={isDrilled}
                              title={
                                isDrilled
                                  ? "もう一度押すと解除します"
                                  : "この行で明細を絞り込みます"
                              }
                              onClick={() => toggleDrill(entry.value)}
                              onKeyDown={(e) => {
                                if (e.key === "Enter" || e.key === " ") {
                                  e.preventDefault();
                                  toggleDrill(entry.value);
                                }
                              }}
                            >
                              <td className="cell col-m wrap ga-breakdown__name">
                                {/* 選んだ指標の大きさを背景の帯で見せる */}
                                <span
                                  className="ga-breakdown__bar"
                                  style={{ width: `${barWidth}%` }}
                                  aria-hidden="true"
                                />
                                <span className="ga-breakdown__text">{label}</span>
                              </td>
                              <td className="cell col-xs nowrap right">
                                {entry.count.toLocaleString()}
                              </td>
                              <td className="cell col-xs nowrap right">
                                {entry.slots.toLocaleString()}
                              </td>
                              <td className="cell col-s nowrap right">
                                {entry.sales.toLocaleString()}
                              </td>
                              <td
                                className={`cell col-s nowrap right ${
                                  entry.profit < 0 ? "is-negative" : ""
                                }`}
                              >
                                {entry.profit.toLocaleString()}
                              </td>
                              <td className="cell col-xs nowrap right">
                                {formatRate(entry.margin) || "-"}
                              </td>
                              <td className="cell col-xs nowrap right">
                                {formatRate(entry.share * 100) || "-"}
                              </td>
                            </tr>
                          );
                        })}
                      </tbody>
                    </table>
                  </div>

                  {hiddenBreakdownCount > 0 && (
                    <button
                      type="button"
                      className="ga-breakdown__more"
                      onClick={() => setShowAllBreakdown(true)}
                    >
                      残り {hiddenBreakdownCount.toLocaleString()} 件を表示
                    </button>
                  )}
                  {showAllBreakdown && breakdown.length > BREAKDOWN_LIMIT && (
                    <button
                      type="button"
                      className="ga-breakdown__more"
                      onClick={() => setShowAllBreakdown(false)}
                    >
                      上位{BREAKDOWN_LIMIT}件に戻す
                    </button>
                  )}
                </div>

                {drill && (
                  <div className="ga-drill">
                    <span className="ga-drill__text">
                      {breakdownDimension?.label}：
                      <strong>
                        {breakdownDimension?.format
                          ? breakdownDimension.format(drill.value) || drill.value
                          : drill.value}
                      </strong>
                      {" "}で明細を絞り込み中
                    </span>
                    <button
                      type="button"
                      className="clear-btn"
                      onClick={() => setDrill(null)}
                    >
                      解除
                    </button>
                  </div>
                )}

                {slot && (
                  <div className="ga-drill">
                    <span className="ga-drill__text">
                      時間帯：<strong>{slotText}</strong> に稼働している案件で絞り込み中
                    </span>
                    <button
                      type="button"
                      className="clear-btn"
                      onClick={() => setSlot(null)}
                    >
                      解除
                    </button>
                  </div>
                )}

                {/* 一覧とヒートマップの切り替え。どちらも上の絞り込みをそのまま使う */}
                <div className="ga-view" role="tablist" aria-label="表示">
                  {[
                    { key: "list", label: "一覧" },
                    { key: "heatmap", label: "時間帯（ヒートマップ）" },
                  ].map((view) => (
                    <button
                      key={view.key}
                      type="button"
                      role="tab"
                      className={`ga-view__tab${listView === view.key ? " is-on" : ""}`}
                      onClick={() => setListView(view.key)}
                      aria-selected={listView === view.key}
                    >
                      {view.label}
                    </button>
                  ))}
                </div>

                {listView === "heatmap" ? (
                  <WorkHeatmap
                    blocks={heatBlocks}
                    metric={heatMetric}
                    onMetricChange={setHeatMetric}
                    categoryCounts={categoryCounts}
                    selectedCats={heatCats}
                    onToggleCat={toggleHeatCat}
                    split={heatSplit}
                    onSplitChange={setHeatSplit}
                    selected={slot}
                    onSelect={selectSlot}
                    excluded={heatmap.excluded}
                    transpose={isNarrow}
                  />
                ) : (
                  <>
                    <div className="ga-list-info">
                      <span>
                        {startIndex}–{endIndex} / {sortedRows.length.toLocaleString()} 件
                      </span>
                      <button
                        type="button"
                        className="ga-export-btn"
                        onClick={handleExport}
                        disabled={exporting || !sortedRows.length}
                      >
                        {exporting
                          ? "作成中..."
                          : `Excelに出力（${sortedRows.length.toLocaleString()}件）`}
                      </button>
                    </div>

                    <Pagination
                      currentPage={currentPage}
                      totalPages={totalPages}
                      onChange={handlePageChange}
                    />

                    {/* カード表示ではヘッダをクリックできないので、並び替えを別に出す */}
                    {isNarrow && (
                      <div className="anken-sort">
                        <label className="anken-sort__label">
                          並び替え
                          <select
                            value={sortConfig.key || ""}
                            onChange={(e) =>
                              setSortConfig((prev) => ({
                                ...prev,
                                key: e.target.value || null,
                              }))
                            }
                          >
                            <option value="">指定なし</option>
                            {HEADERS.map((h) => (
                              <option key={h.key} value={h.key}>
                                {h.label}
                              </option>
                            ))}
                          </select>
                        </label>
                        <button
                          type="button"
                          className="anken-sort__order"
                          onClick={() =>
                            setSortConfig((prev) => ({
                              ...prev,
                              direction: prev.direction === "asc" ? "desc" : "asc",
                            }))
                          }
                          disabled={!sortConfig.key}
                        >
                          {sortConfig.direction === "asc" ? "▲ 昇順" : "▼ 降順"}
                        </button>
                      </div>
                    )}

                    {isNarrow ? (
                      <div className="anken-cards">
                        {pageRows.map((row) => (
                          <div
                            className={`anken-card ${contractTypeClass(row)}`}
                            key={row["Id"]}
                          >
                            {/* 上段：主管・支店・区分・コマ・拘束。
                                区分は大きさを他と揃え、色だけで見分けさせる */}
                            <div className="anken-card__tags ga-card-top">
                              <span className="anken-tag">
                                {groupLabel(row["Group_FY22__c"]) || "主管不明"}
                              </span>
                              {row["Branch__c"] && (
                                <span className="anken-tag">{row["Branch__c"]}</span>
                              )}
                              {row["Partner_Keiyaku_type_temp__c"] && (
                                <span className={`anken-tag ga-type ${contractTypeClass(row)}`}>
                                  {row["Partner_Keiyaku_type_temp__c"]}
                                </span>
                              )}
                              <span className="anken-tag">
                                {row["KADO_YOTEI_NISSUU_AUTO__c"] || 0}コマ
                              </span>
                              <span className="anken-tag">
                                拘束 {formatHours(workHours(row))}
                              </span>
                            </div>

                            <div className="anken-card__head">
                              <div className="anken-card__partner">
                                {renderCell({ key: "Name" }, row)}
                              </div>
                              <div
                                className={`anken-card__rate ${
                                  toNumber(row["Yotei_Arari_Keisan__c"]) < 0 ? "is-negative" : ""
                                }`}
                              >
                                <span className="anken-card__rate-label">粗利率</span>
                                {formatRate(grossMarginPct(row)) || "-"}
                              </div>
                            </div>

                            <div className="anken-card__project">
                              <span className="anken-card__label">パートナー</span>
                              {renderCell({ key: "Partner__r.Name" }, row)}
                            </div>

                            {/* 「誰に聞けばよいか」はパートナー名の直後で見たいので、
                                上段のタグ列ではなくここに置く */}
                            <div className="anken-card__project ga-card-admin">
                              <span className="anken-card__label">管理担当者</span>
                              {row[ADMIN_KEY] || UNSET}
                            </div>

                            <div className="anken-card__money">
                              {[
                                { label: "売上/月", key: "Scheduled_sales_calculation__c" },
                                { label: "原価/月", key: "Yotei_Genka_keisan__c" },
                                { label: "粗利/月", key: "Yotei_Arari_Keisan__c" },
                              ].map(({ label, key }) => (
                                <div key={key}>
                                  <span className="anken-card__label">{label}</span>
                                  <span
                                    className={
                                      key === "Yotei_Arari_Keisan__c" &&
                                      toNumber(row[key]) < 0
                                        ? "is-negative"
                                        : ""
                                    }
                                  >
                                    {formatMoney(row[key]) || "-"}
                                  </span>
                                  <span className="ga-sub">
                                    （{formatComputed(perDay(row, key), "/日")}）
                                  </span>
                                </div>
                              ))}
                            </div>

                            <div className="ga-card-hourly">
                              <span className="anken-card__label">売上/時</span>
                              <span className="ga-card-hourly__value">
                                {formatComputed(salesPerHour(row))}
                              </span>
                            </div>

                            <div className="anken-card__start">
                              {formatArea(row) || "稼働地不明"}
                              <br />
                              {row["OperationStartDate__c"] || "開始日不明"} 〜{" "}
                              {formatEndDate(row["OperationEndDate__c"]) || "不明"}
                              <br />
                              {formatWorkingDays(row["WorkingDay__c"]) || "曜日不明"}{" "}
                              {formatTime(row["OperationStartTime__c"])}
                              {row["OperationEndTime__c"] &&
                                `〜${formatTime(row["OperationEndTime__c"])}`}
                            </div>

                            {row["Haisyasinsei_komento__c"] && (
                              <div className="anken-card__comment">
                                {row["Haisyasinsei_komento__c"]}
                              </div>
                            )}
                          </div>
                        ))}
                      </div>
                    ) : (
                      <div className="anken-table-scroll">
                        <table className="anken-table">
                          <thead>
                            <tr>
                              {HEADERS.map((h) => (
                                <th
                                  key={h.key}
                                  className={`cell th-click ${h.w || ""} ${h.right ? "right" : ""}`}
                                  onClick={() => handleSort(h.key)}
                                  title="クリックで並び替え"
                                >
                                  {h.label}
                                  {sortConfig.key === h.key &&
                                    (sortConfig.direction === "asc" ? " ▲" : " ▼")}
                                </th>
                              ))}
                            </tr>
                          </thead>
                          <tbody>
                            {pageRows.map((row) => (
                              <tr key={row["Id"]}>
                                {HEADERS.map((h) => (
                                  <td
                                    key={h.key}
                                    className={`cell ${h.w || ""} ${
                                      h.wrap ? "wrap" : "nowrap"
                                    } ${h.right ? "right" : ""}`}
                                  >
                                    {renderCell(h, row)}
                                  </td>
                                ))}
                              </tr>
                            ))}
                          </tbody>
                        </table>
                      </div>
                    )}

                    <Pagination
                      currentPage={currentPage}
                      totalPages={totalPages}
                      onChange={handlePageChange}
                    />
                  </>
                )}
              </>
            )}
          </>
        )}
      </div>

      <ScrollTopButton />
      {/* 先に「更新日時」だけを読み、シートが書き換わっていなければ取り直さない */}
      <PullToRefresh
        onRefresh={async () => {
          await syncSheetCaches();
          await loadData({ silent: true });
        }}
      />
    </div>
  );
};

export default GeneralAnalysisPage;
